needs_syncthing = pytest.mark.skipif(not HAS_SYNCTHING, reason="syncthing is not installed")

# Real IDs generated by syncthing itself — the check-digit implementation is
# pinned against these, not against a recollection of the algorithm.
ID_A = "QTCVEVD-H6ZWRX3-ZPCBSCZ-VVKRWH5-Z6BUWYM-2JJSKZ6-PNCFRA6-KDWYEAY"
ID_B = "JIUHQOT-SGRZZAM-SUXXOQJ-KZQSSLX-Q2BJAIC-UYWHSDZ-SNX5LXR-2HQKFQW"
API_KEY = "testkey-does-not-leak"


def req(**overrides) -> Request:
    args = {
        "server_id": ID_B,
        "server_name": "Storage server",
        "folder_id": "shared/docs",
        "folder_path": Path("/srv/shared"),
        "mode": "sendreceive",
    }
    args.update(overrides)
    return Request(**args)


def config(devices=(), folders=()) -> dict:
    return {"devices": list(devices), "folders": list(folders)}


def device(device_id: str, name: str = "a device") -> dict:
    return {"deviceID": device_id, "name": name, "addresses": ["dynamic"]}


def folder(
    folder_id: str, path: str, ftype: str = "sendreceive", devices=()
) -> dict:
    return {
        "id": folder_id,
        "label": folder_id,
        "path": path,
        "type": ftype,
        "devices": [{"deviceID": d} for d in devices],
    }


# -- device IDs ---------------------------------------------------------------


def test_real_device_ids_are_valid():
    assert model.device_id_problem(ID_A) is None
    assert model.device_id_problem(ID_B) is None


def test_a_flipped_check_char_is_rejected():
    # syncthing itself answers 400 to this string (measured).
    assert "check digit" in model.device_id_problem(ID_B[:-1] + "A")


def test_a_flipped_data_char_is_rejected():
    flipped = ID_A[:3] + ("Z" if ID_A[3] != "Z" else "Y") + ID_A[4:]
    assert model.device_id_problem(flipped) is not None


def test_lowercase_and_dashless_ids_normalise_and_validate():
    assert model.normalize_device_id(ID_A.lower()) == ID_A
    assert model.normalize_device_id(ID_A.replace("-", "")) == ID_A
    assert model.device_id_problem(ID_A.lower()) is None
    assert model.device_id_problem(ID_A.replace("-", "")) is None


def test_wrong_length_and_bad_charset_give_reasons():
    assert "56" in model.device_id_problem(ID_A[:20])
    problem = model.device_id_problem("0" * 56)
    assert "invalid characters" in problem
    # 0, 1, 8 are not in the base32 alphabet at all.
    assert "invalid characters" in model.device_id_problem(ID_A[:13] + "018" + ID_A[16:])


# -- paths_overlap ------------------------------------------------------------


def test_paths_overlap():
    assert model.paths_overlap(Path("/a/sync"), Path("/a/sync"))
    assert model.paths_overlap(Path("/a/sync/inside"), Path("/a/sync"))
    assert model.paths_overlap(Path("/a"), Path("/a/sync"))
    # The shared-prefix sibling is the case a naive startswith() gets wrong.
    assert not model.paths_overlap(Path("/a/sync"), Path("/a/sync2"))
    assert not model.paths_overlap(Path("/a/sync"), Path("/b/other"))


# -- plan() -------------------------------------------------------------------


def test_plan_refuses_the_local_id():
    outcome = model.plan(config(), ID_B, req(server_id=ID_B))
    assert isinstance(outcome, model.Refusal)


def test_plan_refuses_a_conflicting_folder_path():
    cfg = config(folders=[folder("shared/docs", "/elsewhere")])
    outcome = model.plan(cfg, ID_A, req())
    assert isinstance(outcome, model.Refusal)
    assert "GUI" in outcome.reason


def test_plan_refuses_a_conflicting_folder_type():
    cfg = config(folders=[folder("shared/docs", "/srv/shared", ftype="receiveonly")])
    outcome = model.plan(cfg, ID_A, req(mode="sendreceive"))
    assert isinstance(outcome, model.Refusal)


def test_plan_refuses_an_overlapping_folder():
    cfg = config(folders=[folder("other", "/srv")])
    outcome = model.plan(cfg, ID_A, req())
    assert isinstance(outcome, model.Refusal)
    assert "overlap" in outcome.reason


def test_an_existing_device_is_not_readded_or_renamed():
    cfg = config(devices=[device(ID_B, name="My NAS")])
    outcome = model.plan(cfg, ID_A, req(server_name="Something else"))
    assert isinstance(outcome, model.Plan)
    assert outcome.add_device is False
    assert outcome.folder_action == "create"


def test_plan_create_share_and_none():
    create = model.plan(config(), ID_A, req())
    assert create.add_device and create.folder_action == "create"

    existing = folder("shared/docs", "/srv/shared", devices=[ID_A])
    share = model.plan(config(folders=[existing]), ID_A, req())
    assert share.folder_action == "share"

    done = folder("shared/docs", "/srv/shared", devices=[ID_A, ID_B])
    none = model.plan(config(devices=[device(ID_B)], folders=[done]), ID_A, req())
    assert none.folder_action == "none" and none.add_device is False


# -- build_* ------------------------------------------------------------------


def test_build_folder_create_has_both_devices_and_an_absolute_path(tmp_path):
    template = {"devices": [{"deviceID": ID_A}], "type": "sendreceive", "paused": False}
    request = req(folder_path=tmp_path / "sync")
    built = model.build_folder(template, ID_A, request, "create")
    ids = {d["deviceID"] for d in built["devices"]}
    assert ids == {ID_A, ID_B}
    assert Path(built["path"]).is_absolute()
    assert built["path"] == str((tmp_path / "sync").resolve())
    assert built["type"] == "sendreceive"
    assert built["id"] == "shared/docs"  # an id containing / is fine


def test_build_device_comes_from_the_defaults_template():
    built = model.build_device({"compression": "metadata", "ignored": "kept"}, req())
    assert built["deviceID"] == ID_B
    assert built["name"] == "Storage server"
    assert built["addresses"] == ["dynamic"]
    assert built["introducer"] is False
    assert built["autoAcceptFolders"] is False
    assert built["ignored"] == "kept"


