def test_verify_catches_the_silently_dropped_device_entry():
    """Fact 2: a devices entry for a device not in config is dropped with a 200."""
    cfg = config(
        devices=[device(ID_A), device(ID_B)],
        folders=[folder("shared/docs", "/srv/shared", devices=[ID_A])],
    )
    problems = model.verify(cfg, req())
    assert any("silently" in p for p in problems)


def test_verify_catches_a_coerced_folder_type():
    """Fact 3: an unknown type is stored as sendreceive, not rejected."""
    cfg = config(
        devices=[device(ID_A), device(ID_B)],
        folders=[
            folder("shared/docs", "/srv/shared", ftype="sendreceive", devices=[ID_A, ID_B])
        ],
    )
    problems = model.verify(cfg, req(mode="receiveonly"))
    assert any("coerce" in p for p in problems)


def test_verify_catches_a_missing_device():
    cfg = config(
        devices=[device(ID_A)],
        folders=[folder("shared/docs", "/srv/shared", devices=[ID_A])],
    )
    problems = model.verify(cfg, req())
