# -- discover() -----------------------------------------------------------------


def write_config(tmp_path: Path, address: str, *, tls: bool = False, key: str = API_KEY) -> Path:
    path = tmp_path / "config.xml"
    path.write_text(
        "<configuration>\n"
        f'  <gui enabled="true" tls="{"true" if tls else "false"}">\n'
        f"    <address>{address}</address>\n"
        f"    <apikey>{key}</apikey>\n"
        "  </gui>\n"
        "</configuration>\n"
    )
    return path


def test_discover_plain_loopback(tmp_path):
    endpoint = api.discover(write_config(tmp_path, "127.0.0.1:8384"))
    assert isinstance(endpoint, api.Endpoint)
    assert endpoint.base_url == "http://127.0.0.1:8384"
    assert endpoint.api_key == API_KEY
    assert endpoint.verify_tls is True


def test_discover_wildcard_addresses_map_to_loopback(tmp_path):
    endpoint = api.discover(write_config(tmp_path, "0.0.0.0:8384"))
    assert isinstance(endpoint, api.Endpoint) and endpoint.base_url == "http://127.0.0.1:8384"
    endpoint = api.discover(write_config(tmp_path, "[::]:8384"))
    assert isinstance(endpoint, api.Endpoint) and endpoint.base_url == "http://[::1]:8384"


def test_discover_tls_on_loopback_disables_verification(tmp_path):
    endpoint = api.discover(write_config(tmp_path, "127.0.0.1:8384", tls=True))
    assert isinstance(endpoint, api.Endpoint)
    assert endpoint.base_url == "https://127.0.0.1:8384"
    assert endpoint.verify_tls is False


def test_discover_refuses_a_unix_socket(tmp_path):
    reason = api.discover(write_config(tmp_path, "unix:///run/syncthing/gui.sock"))
    assert isinstance(reason, str) and "unix" in reason


def test_discover_refuses_a_non_loopback_host(tmp_path):
    reason = api.discover(write_config(tmp_path, "192.168.1.50:8384"))
    assert isinstance(reason, str) and "loopback" in reason.lower()


def test_discover_reports_a_missing_config(tmp_path):
    reason = api.discover(tmp_path / "nope.xml")
    assert isinstance(reason, str)


def test_endpoint_repr_never_contains_the_key():
    endpoint = api.Endpoint("http://127.0.0.1:8384", API_KEY, True)
    assert API_KEY not in repr(endpoint)


