def test_the_bundled_scripts_have_no_command_substitution_in_strings():
    """A backtick or `$(` inside a double-quoted `echo` runs the command — the
    first draft's 'left `loginctl enable-linger` alone' line literally ran it."""
    from dev_setup import registry

    registry.init()
    tool = registry.get("syncthing")
    for script in (tool.install_script, tool.remove_script):
        assert "`" not in script
        assert "$(" not in script


# -- the wizard ----------------------------------------------------------------


class FakeClient:
    """Stands in for api.Client; records POST order and returns canned reads."""

    def __init__(self, endpoint, *, config_data=None, myID=ID_A):
        self.endpoint = endpoint
        self.posts: list[tuple[str, object]] = []
        self._config = config_data or config(devices=[device(ID_A)])
        self._myID = myID
        # Written state so the post-write GET can answer truthfully.
        self.written_devices: list[dict] = []
        self.written_folders: list[dict] = []

    def get(self, path):
        if path == "/rest/config":
            return {
                "devices": self._config.get("devices", []) + self.written_devices,
                "folders": self._config.get("folders", []) + self.written_folders,
            }
        if path == "/rest/system/status":
            return {"myID": self._myID}
        if path == "/rest/config/defaults/device":
            return {"addresses": ["dynamic"], "introducer": True}
        if path == "/rest/config/defaults/folder":
            return {"devices": [{"deviceID": ID_A}], "type": "sendreceive", "paused": False}
        return {}

    def post(self, path, data):
        self.posts.append((path, data))
        if path == "/rest/config/devices":
            self.written_devices.append(data)
        if path == "/rest/config/folders":
            self.written_folders.append(data)
        return {}


