# -- against the real binary -----------------------------------------------------


def _free_port() -> int:
    with socket.socket() as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


def _wait_for(predicate, timeout: float, what: str):
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        value = predicate()
        if value:
            return value
        time.sleep(0.5)
    raise AssertionError(f"timed out waiting for {what}")


@pytest.fixture
def two_daemons(tmp_path):
    """Two throwaway syncthing instances; never touches the real config/service."""
    homes = {}
    endpoints = {}
    procs = []
    for name in ("a", "b"):
        home = tmp_path / name
        subprocess.run(
            ["syncthing", "generate", f"--home={home}"],
            check=True,
            capture_output=True,
            # syncthing panics at startup when $HOME is unset; give it the tmp dir.
            env={"STNOUPGRADE": "1", "PATH": "/usr/bin:/bin", "HOME": str(tmp_path)},
        )
        homes[name] = home
    # Both configs are generated before either daemon listens, so both can be
    # probed onto the same port — pin each to a distinct free TCP port, and drop
    # the relay/quic entries, so A can be pointed at B deterministically.
    ports = {}
    for name in ("a", "b"):
        ports[name] = _free_port()
        cfg_path = homes[name] / "config.xml"
        cfg_path.write_text(
            re.sub(
                r"\s*<listenAddress>.*?</listenAddress>",
                "",
                cfg_path.read_text(),
            ).replace(
                "</options>",
                f"        <listenAddress>tcp://127.0.0.1:{ports[name]}</listenAddress>\n    </options>",
            )
        )
    b_port = ports["b"]
    try:
        for name in ("a", "b"):
            log = open(tmp_path / f"{name}.log", "w")  # noqa: SIM115 — kept open for the daemon's lifetime
            procs.append(
                subprocess.Popen(
                    [
                        "syncthing", "serve", "--no-browser", "--no-restart",
                        "--no-upgrade", "--log-level=WARN", f"--home={homes[name]}",
                    ],
                    stdout=log, stderr=subprocess.STDOUT,
                    stdin=subprocess.DEVNULL,
                    env={"STNOUPGRADE": "1", "PATH": "/usr/bin:/bin", "HOME": str(tmp_path)},
                )
            )
            endpoint = api.discover(homes[name] / "config.xml")
            assert isinstance(endpoint, api.Endpoint)
            endpoints[name] = endpoint
            _wait_for(
                lambda e=endpoint: api.wait_ready(e, timeout=2),
                timeout=30,
                what=f"syncthing {name} API",
            )
        yield endpoints, homes, b_port
    finally:
        for proc in procs:
            proc.kill()
        # `serve` detaches its worker into its own session, so a group kill on
        # the monitor misses it — match the unique --home path instead.
        for home in homes.values():
            subprocess.run(
                ["pkill", "-KILL", "-f", re.escape(f"--home={home}")], capture_output=True
            )
        for proc in procs:
            proc.wait(timeout=10)


@needs_syncthing
def test_pairing_two_real_instances(two_daemons, tmp_path):
    endpoints, _, b_port = two_daemons
    a, b = api.Client(endpoints["a"]), api.Client(endpoints["b"])
    id_a = a.get("/rest/system/status")["myID"]
    id_b = b.get("/rest/system/status")["myID"]

    request = Request(
        server_id=id_b,
        server_name="instance b",
        # An id with a slash is the shape `PUT /rest/config/folders/<id>` 404s
        # on — the collection POST has to carry it.
        folder_id="shared/dir one",
        folder_path=tmp_path / "shared",
        mode="receiveonly",
    )
    config_a = a.get("/rest/config")
    outcome = model.plan(config_a, id_a, request)
    assert isinstance(outcome, model.Plan)
    wizard.apply(a, config_a, id_a, request, outcome)
    assert model.verify(a.get("/rest/config"), request) == []

    # Point A at B's real address so the connection doesn't wait on discovery.
    device_b = next(
        d for d in a.get("/rest/config")["devices"] if d.get("deviceID") == id_b
    )
    a.post("/rest/config/devices", {**device_b, "addresses": [f"tcp://127.0.0.1:{b_port}"]})
    pending = _wait_for(
        lambda: id_a in b.get("/rest/cluster/pending/devices"),
        timeout=15,
        what="A appearing in B's pending devices",
    )
    assert pending


@needs_syncthing
def test_the_silent_drop_and_type_coercion_the_wizard_guards(two_daemons, tmp_path):
    """If a future syncthing starts *rejecting* these, the wizard's write order
    and verify() are solving a problem that no longer exists — this test is the
    tripwire."""
    a = api.Client(two_daemons[0]["a"])
    id_a = a.get("/rest/system/status")["myID"]

    # A folder entry naming a device that is not in config.devices is dropped.
    a.post("/rest/config/folders", {
        "id": "drop-probe",
        "path": str(tmp_path / "drop"),
        "type": "sendreceive",
        "devices": [{"deviceID": id_a}, {"deviceID": ID_B}],
    })
    stored = next(
        f for f in a.get("/rest/config")["folders"] if f.get("id") == "drop-probe"
    )
    assert [d["deviceID"] for d in stored["devices"]] == [id_a]

    # A bogus folder type is stored as sendreceive rather than rejected.
    a.post("/rest/config/folders", {
        "id": "type-probe",
        "path": str(tmp_path / "type"),
        "type": "bogus",
        "devices": [{"deviceID": id_a}],
    })
    stored = next(
        f for f in a.get("/rest/config")["folders"] if f.get("id") == "type-probe"
    )
    assert stored["type"] == "sendreceive"
